// Helpers called from the code generated by `@Equatable`.
//
// The generated `==` and `hash(into:)` go through these overloads instead of calling `==` and
// `hasher.combine` directly. Overload resolution then picks the right strategy per property:
//
// - `Equatable` types are compared with `==` (and hashed with `hasher.combine`).
// - classes that are not `Equatable` are compared by identity (`===`) and hashed by `ObjectIdentifier`.
// - classes that are `Equatable` keep their own `==`; if they are also `Hashable`, they are hashed
//   with `hasher.combine`, otherwise they don't contribute to the hash (which keeps `hash(into:)`
//   consistent with `==`).
// - tuples of `Equatable` elements are compared element-wise, like the standard library's tuple `==`.
// - metatypes are compared and hashed by identity, like the standard library's `Any.Type` `==`.
//
// These are public only because macro expansions must be able to call them. Don't call them directly.

// swiftlint:disable identifier_name large_tuple

// MARK: - Equality

@inlinable
public func _$isEqual<T: Equatable>(_ lhs: T, _ rhs: T) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<T: AnyObject>(_ lhs: T, _ rhs: T) -> Bool {
    lhs === rhs
}

@inlinable
public func _$isEqual<T: Equatable & AnyObject>(_ lhs: T, _ rhs: T) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<T: AnyObject>(_ lhs: T?, _ rhs: T?) -> Bool {
    lhs === rhs
}

@inlinable
public func _$isEqual<T: Equatable & AnyObject>(_ lhs: T?, _ rhs: T?) -> Bool {
    lhs == rhs
}

/// Metatypes aren't `Equatable`, but the standard library compares them by identity.
@inlinable
public func _$isEqual(_ lhs: Any.Type, _ rhs: Any.Type) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<A: Equatable, B: Equatable>(
    _ lhs: (A, B),
    _ rhs: (A, B)
) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<A: Equatable, B: Equatable, C: Equatable>(
    _ lhs: (A, B, C),
    _ rhs: (A, B, C)
) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<A: Equatable, B: Equatable, C: Equatable, D: Equatable>(
    _ lhs: (A, B, C, D),
    _ rhs: (A, B, C, D)
) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<A: Equatable, B: Equatable, C: Equatable, D: Equatable, E: Equatable>(
    _ lhs: (A, B, C, D, E),
    _ rhs: (A, B, C, D, E)
) -> Bool {
    lhs == rhs
}

@inlinable
public func _$isEqual<A: Equatable, B: Equatable, C: Equatable, D: Equatable, E: Equatable, F: Equatable>(
    _ lhs: (A, B, C, D, E, F),
    _ rhs: (A, B, C, D, E, F)
) -> Bool {
    lhs == rhs
}

// MARK: - Hashing

@inlinable
public func _$hash(_ value: some Hashable, into hasher: inout Hasher) {
    hasher.combine(value)
}

@inlinable
public func _$hash(_ value: some AnyObject, into hasher: inout Hasher) {
    hasher.combine(ObjectIdentifier(value))
}

@inlinable
public func _$hash(_ value: some Hashable & AnyObject, into hasher: inout Hasher) {
    hasher.combine(value)
}

/// An `Equatable` class that isn't `Hashable` defines equality itself, so hashing it by identity
/// would break the `Hashable` contract. Contributing nothing to the hash is always consistent.
@inlinable
public func _$hash(_: some Equatable & AnyObject, into _: inout Hasher) {}

@inlinable
public func _$hash(_ value: (some AnyObject)?, into hasher: inout Hasher) {
    hasher.combine(value.map(ObjectIdentifier.init))
}

@inlinable
public func _$hash(_ value: (some Hashable & AnyObject)?, into hasher: inout Hasher) {
    hasher.combine(value)
}

/// Metatypes are hashed by identity, consistent with how `_$isEqual` compares them.
@inlinable
public func _$hash(_ value: Any.Type, into hasher: inout Hasher) {
    hasher.combine(ObjectIdentifier(value))
}

/// See the non-optional `Equatable & AnyObject` overload.
@inlinable
public func _$hash(_: (some Equatable & AnyObject)?, into _: inout Hasher) {}

// swiftlint:enable identifier_name large_tuple
